DB.RW = DB.RW || {};
Object.assign(DB.RW, {
"sodium-sulfate-potassium-sulfate-magnesium-sulfate":{rl:"Split-dose sulfate bowel prep per label: two 6-ounce doses, each diluted to 16 ounces and followed by two 16-ounce containers of water, finished 2 hours before colonoscopy; dehydration and electrolyte shifts are the key risks.",rh:"Severe vomiting, abdominal pain or distension, syncope, confusion or seizure typically prompt holding the prep and notifying the provider.",ml:"Osmotic sulfate-based bowel cleansing agent labeled for colonoscopy preparation in adults and children 12 years and older.",mp:"Osmotic preps are linked to hyponatremia, seizures, arrhythmias and AKI, especially with diuretics, ACE inhibitors, ARBs or NSAIDs; split dosing improves cleansing."},
"rifamycin":{rl:"Oral minimally absorbed rifamycin, 388 mg (two tablets) twice daily for 3 days per label, swallowed whole; not effective for diarrhea with fever or blood.",rh:"Fever, bloody stool, worsening diarrhea or signs of dehydration typically prompt notifying the provider.",ml:"Delayed-release colonic rifamycin (Aemcolo) labeled for travelers' diarrhea caused by noninvasive E. coli in adults.",mp:"Like rifaximin it acts locally in the gut; invasive pathogens (Campylobacter, Shigella, Salmonella) are outside its labeled use."},
"vonoprazan-amoxicillin":{rl:"Vonoprazan 20 mg twice daily plus amoxicillin 1000 mg three times daily for 14 days per label; penicillin allergy and rilpivirine are key screening points.",rh:"Rash, facial swelling, wheezing or severe diarrhea typically prompt holding and notifying the provider.",ml:"Co-packaged potassium-competitive acid blocker plus amoxicillin (Voquezna Dual Pak) labeled for H. pylori infection in adults.",mp:"Potent acid suppression by vonoprazan allows high-dose amoxicillin dual therapy without clarithromycin."},
"bismuth-metronidazole-tetracycline":{rl:"Three capsules four times daily after meals and at bedtime with omeprazole 20 mg twice daily for 10 days per label; alcohol, pregnancy and dairy or antacid timing are key points.",rh:"Neurologic symptoms (numbness, confusion, seizure), severe rash, pregnancy or a disulfiram-like reaction typically prompt holding and notifying the provider.",ml:"Bismuth subcitrate potassium, metronidazole and tetracycline capsule (Pylera) labeled with omeprazole for H. pylori with duodenal ulcer disease.",mp:"Bismuth quadruple therapy is a standard regimen where clarithromycin resistance is common; bismuth causes harmless black stools."},
"omeprazole-amoxicillin-rifabutin":{rl:"Four capsules three times daily with food for 14 days per label (omeprazole 40 mg, amoxicillin 1000 mg, rifabutin 50 mg per dose); orange-red body fluids are expected.",rh:"Rash, facial swelling, eye pain or redness, or severe diarrhea typically prompt holding and notifying the provider.",ml:"All-in-one omeprazole, amoxicillin and rifabutin capsule (Talicia) labeled for H. pylori infection in adults.",mp:"H. pylori resistance to rifabutin is rare, but rifabutin induces CYP3A4 and lowers hormonal contraceptive and many antiretroviral levels."},
"lansoprazole-amoxicillin-clarithromycin":{rl:"Lansoprazole 30 mg, amoxicillin 1 g and clarithromycin 500 mg together twice daily for 10 or 14 days per label; clarithromycin drug interactions and QT are key risks.",rh:"Palpitations, syncope, muscle pain, rash or severe diarrhea typically prompt holding and notifying the provider.",ml:"Co-packaged clarithromycin triple therapy (Prevpac and generics) labeled for H. pylori with duodenal ulcer disease.",mp:"Clarithromycin is a strong CYP3A4 inhibitor (statin rhabdomyolysis, colchicine toxicity) and prolongs QT; triple therapy falls short where clarithromycin resistance is high."},
"cefadroxil":{rl:"Oral first-generation cephalosporin, 1 to 2 g per day once or divided twice daily per label; interval extended in renal impairment.",rh:"Hives, wheezing, facial swelling or severe diarrhea typically prompt holding and notifying the provider.",ml:"First-generation cephalosporin labeled for UTIs, skin and skin structure infections and group A streptococcal pharyngitis.",mp:"Cefadroxil shares its R1 side chain with amoxicillin, which matters for cross-reactivity in amoxicillin allergy."},
"cefprozil":{rl:"Oral second-generation cephalosporin, 250 to 500 mg every 12 to 24 hours per label by indication; half dose below creatinine clearance 30.",rh:"Hives, wheezing, facial swelling or severe diarrhea typically prompt holding and notifying the provider.",ml:"Second-generation cephalosporin labeled for pharyngitis, otitis media, sinusitis, bronchitis exacerbations and uncomplicated skin infections.",mp:"Second-generation agents add H. influenzae and Moraxella coverage, which suits ear and sinus infections."},
"cefaclor":{rl:"Oral second-generation cephalosporin, 250 mg every 8 hours per label (pediatric 20 to 40 mg/kg/day divided every 8 hours); serum sickness-like reactions are the classic risk.",rh:"Rash with joint pain and fever, hives, wheezing or severe diarrhea typically prompt holding and notifying the provider.",ml:"Second-generation cephalosporin labeled for otitis media, respiratory, urinary and skin infections.",mp:"Cefaclor is the classic cause of serum sickness-like reactions in children."},
"cefotetan":{rl:"IV or IM cephamycin, 1 or 2 g per label, usually every 12 hours; prophylaxis 1 or 2 g once 30 to 60 minutes before surgery; hemolysis and bleeding are key risks.",rh:"A falling hemoglobin, dark urine, jaundice, bleeding or severe allergy typically prompt holding and notifying the provider.",ml:"Cephamycin (second-generation cephalosporin) with anaerobic coverage labeled for surgical prophylaxis and gynecologic, intra-abdominal and other infections.",mp:"The NMTT side chain causes hypoprothrombinemia and disulfiram-like reactions; cefotetan has the highest cephalosporin rate of immune hemolytic anemia."}
});

