Object.assign(DB.RW, {
"ravulizumab":{rl:"IV anti-C5 antibody given as a weight-based loading dose then every 8 weeks per label (gMG 3000 to 3600 mg maintenance); boxed warning for meningococcal infection with vaccination at least 2 weeks before starting.",rh:"Fever, headache with neck stiffness, petechial rash, confusion or an infusion reaction typically prompt holding and urgent provider notification.",ml:"Long-acting humanized anti-C5 monoclonal antibody labeled for PNH, aHUS, AChR-positive gMG and AQP4-positive NMOSD.",mp:"Engineered from eculizumab for FcRn recycling, extending dosing to every 8 weeks; terminal complement blockade mimics C5 to C9 deficiency with Neisseria risk."},
"efgartigimod":{rl:"IV FcRn blocker given 10 mg/kg over 1 hour weekly for 4 weeks per cycle (1200 mg cap at 120 kg or more) per label; infections and hypersensitivity are the key risks.",rh:"Active infection, hypersensitivity or infusion reaction, or new respiratory or bulbar weakness typically prompt holding and notifying the provider.",ml:"Engineered IgG1 Fc fragment that blocks FcRn and lowers IgG, labeled for adult generalized myasthenia gravis (subcutaneous Hytrulo also for CIDP).",mp:"FcRn blockade shortens IgG half-life and lowers pathogenic autoantibodies while sparing IgA, IgM and albumin."},
"rozanolixizumab":{rl:"Subcutaneous FcRn-blocking antibody infused weekly for 6 weeks per cycle at 420, 560 or 840 mg by weight per label; headache, infections and aseptic meningitis are key risks.",rh:"Severe headache with fever or neck stiffness, active infection or hypersensitivity typically prompt holding and notifying the provider.",ml:"Humanized IgG4 anti-FcRn monoclonal antibody labeled for adult gMG that is anti-AChR or anti-MuSK antibody positive.",mp:"Labeled for MuSK-positive gMG, a subtype in which complement inhibitors are not used because MuSK antibodies are mainly IgG4."},
"onasemnogene-abeparvovec":{rl:"One-time IV AAV9 SMN1 gene therapy at 1.1 x 10^14 vg/kg over 60 minutes in children under 2 years per label, with prednisolone before and after; boxed warning for acute liver failure.",rh:"Jaundice, vomiting, rising liver enzymes, bruising or low platelets, reduced urine output or signs of infection typically prompt urgent provider notification.",ml:"AAV9 vector gene replacement therapy delivering SMN1, labeled for SMA in pediatric patients less than 2 years of age.",mp:"SMA results from homozygous SMN1 loss; SMN2 copy number modifies severity; treatment earliest in life gives the best motor outcomes."},
"armodafinil":{rl:"Oral C-IV wake-promoting agent, 150 to 250 mg each morning for OSA or narcolepsy or 150 mg about 1 hour before a shift per label; serious rash and contraceptive failure are key risks.",rh:"Rash, mucosal lesions, chest pain, palpitations or psychiatric symptoms typically prompt holding and notifying the provider.",ml:"R-enantiomer of modafinil (DAT inhibitor) labeled for excessive sleepiness in narcolepsy, OSA and shift work disorder.",mp:"Induces CYP3A4 and inhibits CYP2C19; lowers hormonal contraceptive efficacy; SJS risk as with modafinil."},
"solriamfetol":{rl:"Oral C-IV DNRI started at 75 mg (narcolepsy) or 37.5 mg (OSA) once daily on waking, maximum 150 mg per label; raises blood pressure and heart rate.",rh:"Elevated blood pressure, tachycardia, chest pain or new psychiatric symptoms typically prompt holding and notifying the provider.",ml:"Dopamine and norepinephrine reuptake inhibitor labeled for excessive daytime sleepiness in narcolepsy or OSA.",mp:"Excreted about 95% unchanged in urine, so dosing depends on eGFR; contraindicated with MAOIs."},
"pitolisant":{rl:"Oral non-scheduled H3 inverse agonist titrated from 8.9 mg to 17.8 mg and up to 35.6 mg once daily on waking per label; QT prolongation and CYP2D6 interactions are key risks.",rh:"Palpitations, syncope, QT prolongation on ECG or worsening insomnia or mood typically prompt holding and notifying the provider.",ml:"Histamine H3 receptor antagonist/inverse agonist labeled for EDS or cataplexy in adult narcolepsy and EDS in children 6 years and older.",mp:"Increases brain histamine release by blocking presynaptic H3 autoreceptors; not a controlled substance."},
"lemborexant":{rl:"Oral C-IV dual orexin receptor antagonist, 5 mg immediately before bed with at least 7 hours remaining, maximum 10 mg per label; next-day impairment and complex sleep behaviors are key risks.",rh:"Complex sleep behaviors, marked next-day sedation, sleep paralysis or worsening depression typically prompt holding and notifying the provider.",ml:"DORA (OX1R and OX2R antagonist) labeled for adult insomnia with sleep onset or maintenance difficulty.",mp:"Contraindicated in narcolepsy; CYP3A4 substrate with dose limits for weak inhibitors."},
"daridorexant":{rl:"Oral C-IV dual orexin receptor antagonist, 25 to 50 mg within 30 minutes of bed with at least 7 hours remaining per label; 25 mg cap with moderate CYP3A4 inhibitors or moderate hepatic impairment.",rh:"Complex sleep behaviors, marked next-day sedation, sleep paralysis or worsening depression typically prompt holding and notifying the provider.",ml:"DORA labeled for adult insomnia with sleep onset or maintenance difficulty.",mp:"Shortest half-life of the DORAs (about 8 hours); contraindicated in narcolepsy."},
"zaleplon":{rl:"Oral C-IV Z-drug, 10 mg at bedtime for most adults (5 mg elderly, hepatic impairment or with cimetidine), maximum 20 mg per label; boxed warning for complex sleep behaviors.",rh:"Complex sleep behaviors, confusion, respiratory depression with other sedatives or signs of anaphylaxis typically prompt holding and notifying the provider.",ml:"Alpha-1 selective GABA-A positive allosteric modulator labeled for short-term insomnia.",mp:"Half-life about 1 hour, metabolized mainly by aldehyde oxidase; flumazenil reverses Z-drugs."}
});

